<?phpApp::uses('AppController', 'Controller');App::uses('AccountReportsController','Controller');class SocietySmsController extends AppController {    var $components = array('Paginator','Session', 'RequestHandler', 'Util', 'SocietyBill');    public $helpers = array('Js');    public $societyloginID = '';    public $societyBillingFrequencyId = 0;    public function beforeFilter() {        parent::beforeFilter();        $this->layout = 'society_dashboard';        $this->societyloginID = $this->Session->read('Auth.User.id');        $this->set("utilObj", $this->Util);        $this->set("societyObj", $this->SocietyBill);        $this->loadModel('User');        $this->loadModel('Member');        $this->loadModel('Wing');        $this->loadModel('Tenant');        $this->loadModel('Society');        $this->loadModel('MemberPayment');        $this->loadModel('CashWithdraw');        $this->loadModel('SocietyPayment');        $this->loadModel('MemberBillSummary');        $this->loadModel('SocietyParameter');        $this->loadModel('MemberBillGenerate');        $this->loadModel('SocietyOtherIncome');        $this->loadModel('SocietyLedgerHeads');        $this->loadModel('SocietyHeadSubCategory');        $this->loadModel('AccountHead');        $this->loadModel('JournalVoucher');        $this->loadModel('MemberBillSummarySettlement');        $this->loadModel('MemberBillSettlement');        $this->loadModel('MemberIdentification');        $this->loadAllNavigationModals();        App::import('Vendor', 'dompdf', array('file' => 'dompdf' . DS . 'dompdf_config.inc.php'));    }   function loadAllNavigationModals() {        $this->SocietyBill->getSocietyBuildingLists();        $this->SocietyBill->getSocietyLedgerHeadsDetails();        $this->SocietyBill->navigateSocietyMemberDetails();        $this->SocietyBill->loadAllNavigationModalsDropdowns();        if ($this->societyloginID) {            $billingFrequencyData = $this->Society->SocietyParameter->find('first', array('conditions' => array('SocietyParameter.society_id' => $this->societyloginID)));            if (isset($billingFrequencyData) && count($billingFrequencyData) > 0) {                $this->societyBillingFrequencyId = $billingFrequencyData['SocietyParameter']['billing_frequency_id'];            }        }    }            function account_dues_member(){        $reportType = '';        $societyLoginId = $this->Session->read('Auth.User.id');        if (isset($this->request->data['sms_data']['report_type']) && !empty($this->request->data['sms_data']['report_type'])) {            $reportType = $this->request->data['sms_data']['report_type'];        }                $accountDuesMemberSummary  = [];        $this->Member->unbindModel(                array('hasMany' => array('MemberTariffDetails', 'MemberTariff', 'MemberBillSummary', 'MemberPayment')), false        );        $this->Member->unbindModel(            array('belongsTo' => array('Society', 'Building', 'Wing')), false        );        $societyLoginId = $this->societyloginID;        $optionsMember = array('Member.society_id' => $societyLoginId);        $societyMemberListsForDuesReport = $this->Member->find('all', array('conditions' => $optionsMember, 'order' => array('Member.id' => 'asc')));        $accountDuesMemberSummary = array();                        if ($this->request->is(array('post'))) {            $mDuesCounter = 0;            foreach ($societyMemberListsForDuesReport as $memberDuesListData) {                                $options['AND'] = array('MemberBillSummary.member_id' => $memberDuesListData['Member']['id']);                $accObj = new AccountReportsController();                $accObj->constructClasses();                $dueAmount = $accObj->getMembersDueAmount($memberDuesListData, date('Y-m-d'), $reportType);                $dueAmount = json_decode($dueAmount,true);                if ($reportType == 'Detail') {                    $due = $dueAmount['due'];                } else {                    $due = $dueAmount['dueAmount'];                }                                if ($due <= 1) continue;                $accountDuesMemberSummary[$mDuesCounter]['total_dues_amount'] = $dueAmount['dueAmount'];                $accountDuesMemberSummary[$mDuesCounter]['flat_no'] = $memberDuesListData['Member']['flat_no'];                $accountDuesMemberSummary[$mDuesCounter]['date'] = $dueAmount['date'];                $accountDuesMemberSummary[$mDuesCounter]['member_prefix'] = $memberDuesListData['Member']['member_prefix'];                $accountDuesMemberSummary[$mDuesCounter]['phone'] = $memberDuesListData['Member']['member_phone'];                if (!empty($accountDuesMemberSummaryData['MemberBillSummary']['member_id']))                    $accountDuesMemberSummary[$mDuesCounter]['opening_balance'] = $memberDuesListData['Member']['op_principal'];                                        $MemberIdentificationDetails = $this->MemberIdentification->find('first', array('conditions' => array('MemberIdentification.status' => Configure::read('Active'), 'MemberIdentification.society_id' => $this->Session->read('Auth.User.id'), 'MemberIdentification.member_id' => $memberDuesListData['Member']['id']), 'order' => array('MemberIdentification.flat_no' => 'asc')));                if(!empty($MemberIdentificationDetails) && $postData['MemberPayment']['member_record']=='Old'){                    $accountDuesMemberSummary[$mDuesCounter]['member_name'] = $MemberIdentificationDetails['MemberIdentification']['third_member'];                } else {                    $accountDuesMemberSummary[$mDuesCounter]['member_name'] = $memberDuesListData['Member']['member_name'];                }                      $mDuesCounter ++;            }                    }                $this->set(compact('accountDuesMemberSummary'));    }                public function greetings(){        $societyLoginId = $this->societyloginID;        if($this->request->is(array('post'))){            $this->Member->unbindModel(                    array('hasMany' => array('MemberTariffDetails', 'MemberTariff', 'MemberBillSummary', 'MemberPayment')), false            );                $this->Member->unbindModel(                array('belongsTo' => array('Society', 'Building', 'Wing')), false            );                                    $optionsMember = array('Member.society_id' => $societyLoginId);            $societyMembers = $this->Member->find('all', array('conditions' => $optionsMember, 'order' => array('Member.id' => 'asc')));                    $greetingMessage = $this->request->data['greeting_msg'];            if(!empty($greetingMessage) && !empty($societyMembers)){                foreach($societyMembers as $member){                    $phoneNo = $member['Member']['member_phone'];                    if(!empty($phoneNo)){                        $this->send_sms($phoneNo,$greetingMessage);                        }                }            }        }                $this->set(compact(''));    }        public function receipt_acknowledgment(){        $societyLoginId = $this->societyloginID;        $societyMembersPayment = array();        $post = $this->request->data();        if($this->request->is(array('post'))){            $fromDate = $this->request->data['MemberPayment']['from_date'];            $toDate = $this->request->data['MemberPayment']['till_date'];            $sql =  "select * from ( select member_id,sum(amount_paid) as amount_paid from member_payments where society_id = $societyLoginId and  date(payment_date) between '$fromDate' and '$toDate' group by member_id ) payments join members  on payments.member_id = members.id";            $db = connectionManager::getDataSource('default');            $societyMembersPayment = $db->query($sql);                    }                $this->set(compact('societyMembersPayment','post'));                    }        public function send_receipt_acknowledgement(){        $greetingMessage = $this->request->data['greeting_msg'];        if(!empty($greetingMessage) && !empty($societyMembers)){            foreach($societyMembers as $member){                $phoneNo = $member['Member']['member_phone'];                if(!empty($phoneNo)){                    $this->send_sms($phoneNo,$greetingMessage);                    }            }        }                exit;    }        public function generated_bills(){        $societyLoginId = $this->societyloginID;                $sql =  "SELECT member_name,members.flat_no,member_phone,amount_payable,bill_generated_date,bill_due_date FROM `member_bill_summaries` bills join members  on bills.member_id = members.id   where bills.society_id  = $societyLoginId and  bills.bill_generated_date = (select max(bill_generated_date) from member_bill_summaries where society_id  = $societyLoginId)";        $db = connectionManager::getDataSource('default');        $societyBillPayable = $db->query($sql);                                    $this->set(compact('societyBillPayable'));            }        function set_data_for_dues(){        $societyLoginId = $this->societyloginID;        $societyName = $this->Session->read('Auth.User.username');        $memberDuesDataReq = $this->request->data();        $memberDuesData = [];        $memberDuesDecodedReq = [];        if(isset($memberDuesDataReq['formdata'])){            $memberDuesDecodedReq = json_decode($memberDuesDataReq['formdata']);            }                if(!empty($memberDuesDecodedReq)){            foreach($memberDuesDecodedReq as $data){                $memberDuesData[$data->name] = $data->value;            }        }                if(!empty($memberDuesData)){            $arrayCnt = $memberDuesData['table-count'];            $finalData = [];            for($i = 0 ; $i < $arrayCnt ; $i++){                $phoneKey = "phone_$i";                $finalKeyText = "final_input_text_$i";                $bill_due_date = $memberDuesData["bill_due_date_$i"];                $bill_generated_date = $memberDuesData["bill_generated_date_$i"];                $due_amount = $memberDuesData["dues_$i"];                $flatNo = $memberDuesData["flat_no_$i"];                $flatNokey = "flat_no_$i";                                            $societyName = substr(strtoupper($societyName),0,30);                $amoutDue = substr($due_amount,0,8);                $billDate = date('M',strtotime($bill_generated_date));                $billDueDate = date('d-m',strtotime($bill_due_date));                $checked = isset($memberDuesData["checkbox_$i"]) ? 'Y': 'N';                // $finalText = substr($societyName,0,30)."\nDear Member \nPlease pay your Maintenance Rs ".substr($due_amount,0,8)." for ".date('M',strtotime($bill_generated_date))." Flat No ".$flatNo." \nas per due date ".date('d-m',strtotime($bill_due_date))."- EASY LOGICS TECHNOLOGY";                $finalText = "$societyNameDear MemberPlease pay your Maintenance Rs.$amoutDue for $billDate Flat No $flatNoas per due date $billDueDate - EASY LOGICS TECHNOLOGY";                array_push($finalData,[                        $phoneKey => $memberDuesData[$phoneKey],                        $finalKeyText => $finalText, // $memberDuesData[$finalKeyText],                        'checkbox_checked' =>$checked,                        $flatNokey => $memberDuesData[$flatNokey]                    ]);            }                                  $errorString = "";            $errorCnt = 0;            foreach($finalData as $key => $duesData){                $phone = $duesData["phone_$key"];                $flatNo = $duesData["flat_no_$key"];                $finalMessage = $duesData["final_input_text_$key"];                if(!empty($phone) &&  $duesData['checkbox_checked'] == 'Y' && !empty($finalMessage)){                                                $sendSmsResponse =  $this->send_sms($phone,$finalMessage);                   $decodedSmsResponse = json_decode($sendSmsResponse,1);                   $this->writeSmsResToFile($societyName,$societyLoginId,$phone,$decodedSmsResponse,$flatNo);                   if($decodedSmsResponse['status'] != 'success'){                        $message = $decodedSmsResponse['errors'][0]['message'].'----'.$decodedSmsResponse['warnings'][0]['message'];                        $errorCnt++;                        $errorString = $errorString."\n $flatNo -  $phone - $message\n";                   }                }            }            // $this->downloadSmsLogFile();            $result = ($errorCnt > 0 ) ? " \n Error While Sendign to following Number : \n $errorString " : "Succssfully send to all members" ;            echo $result;        }        exit;    }        public function downloadSmsLogFile(){        $filepath = APP.'/tmp/customlog/smslog/'."latest2022_07_05.txt";// path of file        $ctype="application/octet-stream";        header("Pragma:public");        header("Expired:0");        header("Cache-Control:must-revalidate");        header("Content-Control:public");        header("Content-Description: File Transfer");        header("Content-Type: $ctype");        header("Content-Disposition:attachment; filename=\"".basename($file_path)."\"");        header("Content-Transfer-Encoding:binary");        header("Content-Length:".filesize($filepath));        flush();        readfile($filepath);        exit();                $filename = "template_contractor_upload.xlsx";		$filepath = APP.'/tmp/customlog/smslog/'."latest2022_07_05.txt";// path of file		header ( "Pragma: public" );		header ( "Expires: 0" );		header ( "Cache-Control: must-revalidate, post-check=0, pre-check=0" );		header ( "Cache-Control: public" );		header ( "Content-Description: File Transfer" );		header ( "Content-type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" );		header ( "Content-Disposition: attachment; filename=\"" . $filename . "\"" );		header ( "Content-Transfer-Encoding: binary" );		header ( "Content-Length: " . filesize ( $filepath ) );		ob_end_flush ();		@readfile ( $filepath );           }        public function writeSmsResToFile($societyName,$societyLoginId,$mobNumber,$response,$flatNo){        $fileName = "$societyName$societyLoginId_".date("Y_m_d").".txt";        $status = $response['status'];        if(isset($response['errors'])){            $message = $response['errors'][0]['message'].'----'.$response['warnings'][0]['message'];        }        else{            $message = $response['message']['content'];            }                $finalString = "$flatNo  |  $mobNumber | $status  |  $message ".PHP_EOL;        file_put_contents(APP.'/tmp/customlog/smslog/'.$fileName,$finalString,FILE_APPEND);        return true;    }        public function send_sms($receipants,$message){    $apiKey = urlencode('NjY1YTZkNjQ2YTY1NmU0ZjQ4NjM1MTQ1Mzc0MjcyNzg=');	$numbers = array($receipants);	$sender = urlencode('ESYLGC');	$message = rawurlencode($message);	$numbers = implode(',', $numbers); 	// Prepare data for POST request	$data = array('apikey' => $apiKey, 'numbers' => $numbers, "sender" => $sender, "message" => $message);	// Send the POST request with cURL	$ch = curl_init('https://api.textlocal.in/send/');	curl_setopt($ch, CURLOPT_POST, true);	curl_setopt($ch, CURLOPT_POSTFIELDS, $data);	curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);	$response = curl_exec($ch);	curl_close($ch); 	 // echo "$receipants ".$response;exit;	// Process your response here	return  $response;                    }}